fn wait_for_completion(completion: &DsaCompletionRecord, tsc_freq: u64) -> Option<(u64, u8)> { .. }

fn drain_with_drain_descriptor(
    wq: &WqPortal,
    drain_desc: &DsaHwDesc,
    drain_comp: &mut DsaCompletionRecord,
    operation: DsaOperationClass,
    n: usize,
