    poll_event_statuses: Vec<u8>,
    poll_event_latency_tsc_ticks: Vec<u64>,
}

impl IterationTrace {
    fn new(n: usize) -> Self {
        Self {
            submit_start_tscs: vec![0; n],
            submit_end_tscs: vec![0; n],
            poll_event_offsets: vec![0; n],
            poll_event_counts: vec![0; n],
            poll_latency_offsets: vec![0; n],
