648:fn run_probe<S: CompletionStorage>(
649:    wq: &WqPortal,
650:    slots: &mut S,
651:    n: usize,
652:    poll_offset: usize,
653:    operation: DsaOperationClass,
654:    iterations: usize,
655:    tsc_freq: u64,
656:    spec: ProbeSpec,
657:) -> SubmitMarkerMechanismResult {
658:    assert!(n <= slots.len());
659:
660:    let mut accumulator = ProbeAccumulator::default();
661:    let mut seen = vec![false; n];
662:    let mut iteration_trace = IterationTrace::new(n);
663:    let poll_to_next_unfinished = match spec.timing_mode {
664:        TimingMode::PerRead => poll_to_next_unfinished_with_per_read_timing::<S>,
665:        TimingMode::BatchScan => poll_to_next_unfinished_with_batch_timing::<S>,
666:    };
667:
668:    for iteration_index in 0..iterations {
669:        prepare_completions(slots, n, spec.cache_state);
670:        iteration_trace.reset();
671:
672:        let mut next_completion_to_poll = 0_usize;
673:        for submit_index in 0..n {
674:            let submit = measured_call(|| unsafe { wq.submit(slots.descriptor(submit_index)) });
675:            iteration_trace.record_submit(submit_index, submit.start_tsc, submit.end_tsc);
676:
677:            if submit_index >= poll_offset && next_completion_to_poll < n {
678:                poll_to_next_unfinished(
679:                    slots,
680:                    n,
681:                    &mut next_completion_to_poll,
682:                    spec.prefetch_distance_lines,
683:                    &mut accumulator,
684:                    submit_index,
685:                    &mut iteration_trace,
686:                );
687:            }
688:        }
689:
690:        let outcome = wait_for_all_completions(slots, n, &mut seen);
691:        accumulator.record_outcome(n, outcome);
692:        accumulator.record_sample_trace(iteration_trace.to_sample_trace(iteration_index));
693:    }
694:
695:    accumulator.into_result(slots, n, poll_offset, operation, tsc_freq, spec)
696:}
