698:fn prepare_completions<S: CompletionStorage>(slots: &mut S, n: usize, cache_state: CacheState) {
699:    for index in 0..n {
700:        reset_completion(slots.completion_mut(index));
701:    }
702:
703:    match cache_state {
704:        CacheState::ResetOnly => {}
705:        CacheState::PreTouch => {
706:            for index in 0..n {
707:                core::hint::black_box(slots.completion(index).status());
708:            }
709:        }
710:        CacheState::Clflush => {
711:            flush_range(slots.base_addr() as *const u8, slots.storage_len_bytes());
712:        }
713:    }
