fn poll_to_next_unfinished<S: CompletionStorage>(
    slots: &S,
    n: usize,
    next_completion_to_poll: &mut usize,
    prefetch_distance_lines: usize,
    poll_batch_size: PollBatchSize,
    accumulator: &mut ProbeAccumulator,
    submit_index: usize,
    iteration_trace: &mut IterationTrace,
) {
    let mut current_line = None;
    let mut visible_reads_in_line = 0_u64;
    let mut total_reads = 0_u64;
    let mut total_visible = 0_u64;
    let mut poll_window_tsc = None;

    iteration_trace.begin_poll_event(submit_index);
    while *next_completion_to_poll < n {
        let batch = measured_call(|| {
            poll_completion_batch(
                slots,
                n,
                next_completion_to_poll,
                prefetch_distance_lines,
                poll_batch_size.max_reads(),
                poll_batch_size.records_individual_read_latency(),
                iteration_trace,
            )
        });

        let outcome = batch.value;
        if outcome.reads == 0 {
            break;
        }

        total_reads += outcome.reads;
        total_visible += outcome.visible;

        if poll_batch_size.records_individual_read_latency() {
            debug_assert_eq!(outcome.reads, 1);
            record_single_read_poll_latency(
                slots,
                outcome,
                batch.elapsed_tsc(),
                &mut current_line,
                &mut visible_reads_in_line,
                accumulator,
            );
        } else {
            poll_window_tsc = Some(poll_window_tsc.unwrap_or(0) + batch.elapsed_tsc());
        }

        if outcome.stopped_on_none {
            break;
        }
    }

    if !poll_batch_size.records_individual_read_latency() && total_reads != 0 {
        let latency_tsc = poll_window_tsc.unwrap_or(0);
        accumulator.record_poll_window(latency_tsc, total_reads, total_visible);
        iteration_trace.finish_poll_event(
            submit_index,
            *next_completion_to_poll as u64,
            Some(latency_tsc),
        );
    } else {
        iteration_trace.finish_poll_event(submit_index, *next_completion_to_poll as u64, None);
    }
}

#[derive(Clone, Copy, Default)]
struct PollBatchOutcome {
    reads: u64,
    visible: u64,
    last_index: usize,
    last_status: u8,
    stopped_on_none: bool,
}

fn poll_completion_batch<S: CompletionStorage>(
    slots: &S,
    n: usize,
    next_completion_to_poll: &mut usize,
    prefetch_distance_lines: usize,
    max_reads: usize,
    record_individual_latency: bool,
    iteration_trace: &mut IterationTrace,
) -> PollBatchOutcome {
    let mut outcome = PollBatchOutcome::default();

    while outcome.reads < max_reads as u64 && *next_completion_to_poll < n {
        let completion_index = *next_completion_to_poll;
        prefetch_ahead(slots, completion_index, prefetch_distance_lines);

        let status = DsaCompletionStatus::mask(slots.completion(completion_index).status());
        iteration_trace.record_poll_read(
            completion_index,
            status,
            record_individual_latency.then_some(0),
        );

        outcome.reads += 1;
        outcome.last_index = completion_index;
        outcome.last_status = status;

        if status == DSA_COMP_NONE {
            outcome.stopped_on_none = true;
            break;
        }

        outcome.visible += 1;
        *next_completion_to_poll += 1;
    }

    outcome
}

fn record_single_read_poll_latency<S: CompletionStorage>(
    slots: &S,
    outcome: PollBatchOutcome,
    latency_tsc: u64,
    current_line: &mut Option<usize>,
    visible_reads_in_line: &mut u64,
    accumulator: &mut ProbeAccumulator,
) {
    if outcome.last_status == DSA_COMP_NONE {
        accumulator.record_none(latency_tsc);
        return;
    }

    let line_addr = slots.completion_addr(outcome.last_index) & !(CACHELINE_BYTES - 1);
    if *current_line != Some(line_addr) {
        *current_line = Some(line_addr);
        *visible_reads_in_line = 0;
    }
    *visible_reads_in_line += 1;

    accumulator.record_visible(
        latency_tsc,
        slots.line_position(outcome.last_index),
        *visible_reads_in_line,
    );
}

