660:    wq: &WqPortal,
661:    slots: &mut S,
662:    n: usize,
663:    poll_offset: usize,
664:    operation: DsaOperationClass,
665:    iterations: usize,
666:    tsc_freq: u64,
667:    spec: ProbeSpec,
668:) -> SubmitMarkerMechanismResult {
669:    assert!(n <= slots.len());
670:
671:    let mut accumulator = ProbeAccumulator::default();
672:    let mut seen = vec![false; n];
673:    let mut iteration_trace = IterationTrace::new(n);
674:    let poll_batch_size = spec.poll_batch_size;
675:
676:    for iteration_index in 0..iterations {
677:        prepare_completions(slots, n, spec.cache_state);
678:        iteration_trace.reset();
679:
680:        let mut next_completion_to_poll = 0_usize;
681:        for submit_index in 0..n {
682:            let submit = measured_call(|| unsafe { wq.submit(slots.descriptor(submit_index)) });
683:            iteration_trace.record_submit(submit_index, submit.start_tsc, submit.end_tsc);
684:
685:            if submit_index >= poll_offset && next_completion_to_poll < n {
686:                poll_to_next_unfinished(
687:                    slots,
688:                    n,
689:                    &mut next_completion_to_poll,
690:                    spec.prefetch_distance_lines,
691:                    poll_batch_size,
692:                    &mut accumulator,
693:                    submit_index,
694:                    &mut iteration_trace,
695:                );
696:            }
697:        }
698:
699:        let outcome = wait_for_all_completions(slots, n, &mut seen);
700:        accumulator.record_outcome(n, outcome);
701:        accumulator.record_sample_trace(iteration_trace.to_sample_trace(iteration_index));
702:    }
703:
704:    accumulator.into_result(slots, n, poll_offset, operation, tsc_freq, spec)
705:}
