737:    let mut total_reads = 0_u64;
738:    let mut total_visible = 0_u64;
739:    let mut poll_window_tsc = None;
740:
741:    iteration_trace.begin_poll_event(submit_index);
742:    while *next_completion_to_poll < n {
743:        if poll_batch_size.records_individual_read_latency() {
744:            prefetch_ahead(slots, *next_completion_to_poll, prefetch_distance_lines);
745:        }
