fn record_single_read_poll_latency<S: CompletionStorage>(
    slots: &S,
    outcome: PollBatchOutcome,
    latency_tsc: u64,
    current_line: &mut Option<usize>,
    visible_reads_in_line: &mut u64,
    accumulator: &mut ProbeAccumulator,
    iteration_trace: &mut IterationTrace,
) {
    iteration_trace.record_poll_read(outcome.last_index, outcome.last_status, Some(latency_tsc));

    if outcome.last_status == DSA_COMP_NONE {
        accumulator.record_none(latency_tsc);
        return;
    }

    let line_addr = slots.completion_addr(outcome.last_index) & !(CACHELINE_BYTES - 1);
    if *current_line != Some(line_addr) {
        *current_line = Some(line_addr);
        *visible_reads_in_line = 0;
    }
    *visible_reads_in_line += 1;

    accumulator.record_visible(
        latency_tsc,
        slots.line_position(outcome.last_index),
        *visible_reads_in_line,
    );
}

